package main

const localHTML = `<!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>آزمون مسیر بازی</title><style>body{font:16px Tahoma,sans-serif;background:#111827;color:#e5e7eb;margin:0;padding:24px;line-height:1.9}main{max-width:800px;margin:auto}section{background:#1f2937;border:1px solid #374151;border-radius:20px;padding:22px;margin:20px 0}h1{font-size:25px;color:#fb923c}button{font:inherit;background:#ea580c;color:white;border:0;border-radius:10px;padding:10px 18px;margin:6px;cursor:pointer}button:disabled{opacity:.4;cursor:wait}.row{display:flex;gap:10px;flex-wrap:wrap}small{color:#b8c1ce}code{direction:ltr;display:block;overflow-wrap:anywhere;font-size:12px}#result{color:#fdba74}table{width:100%;font-size:13px;border-collapse:collapse}td,th{text-align:right;padding:10px;border-bottom:1px solid #374151}@media(max-width:500px){body{padding:12px}section{padding:15px}.row button{flex:1}h1{font-size:21px}}</style><main><h1>مسیر مناسب روی اینترنت خودت</h1><p id="game"></p><section><b id="result">در حال دریافت نتیجه…</b><p id="notice"></p><small id="scope"></small><table><thead><tr><th>سرویس آزمون</th><th>مستقیم</th><th>پروکسی</th></tr></thead><tbody id="pairs"></tbody></table><p id="upload"></p><button data-action="retest">آزمون و انتخاب دوباره، پیش از بازی</button><p><small>بعد از انتخاب اولیه، مسیر خودکار قفل می‌شود. آزمون دوره‌ای فقط نتیجه را تازه می‌کند و وسط بازی IP را تغییر نمی‌دهد. روی اینترنت تازه دوباره آزمون کن.</small></p></section><section><h2>آزمون واقعی ورود و مسابقه</h2><p>بازی را کاملاً ببند، مسیر را انتخاب کن و دوباره بازی را روی همین رایانه باز کن؛ سپس نتیجه را ثبت کن. این نتیجه با عنوان «تأیید کاربر» در پنل نمایش داده می‌شود.</p><div class="row"><button data-action="select" data-route="direct">امتحان بازی با مسیر مستقیم</button><button data-action="select" data-route="proxy">امتحان بازی با پروکسی</button></div><div class="row"><button data-action="confirm" data-result="passed">ورود و مسابقه موفق شد</button><button data-action="confirm" data-result="failed">ورود یا مسابقه ناموفق بود</button></div><small>آزمون سرویس ناشر سلامت حساب، NAT یا UDP مسابقه را ثابت نمی‌کند. در تونل کامل انتخاب مسیر برای همهٔ ترافیک عمومی است.</small></section></main><script>
const key=location.hash.slice(1)||sessionStorage.getItem('aria-game-key')||'';if(key)sessionStorage.setItem('aria-game-key',key);history.replaceState(null,'',location.pathname);let selected='proxy';const names={'inconclusive':'نتیجه نامشخص؛ مسیر قبلی حفظ شد','direct-service':'سرویس از مسیر مستقیم پاسخ داد','both-services':'سرویس از هر دو مسیر پاسخ داد','proxy-service':'سرویس فقط از پروکسی پاسخ سالم داد','services-unavailable':'هر دو مسیر سرویس ناموفق بودند','gameplay-direct':'ورود و مسابقه مستقیم، با تأیید کاربر','gameplay-proxy':'ورود و مسابقه از پروکسی، با تأیید کاربر','gameplay-unavailable':'بازی در هر دو مسیر ناموفق، طبق گزارش کاربر'};function el(id){return document.getElementById(id)}async function api(path,body){const r=await fetch(path,{method:body?'POST':'GET',headers:{Authorization:'Bearer '+key,'Content-Type':'application/json'},body:body?JSON.stringify(body):undefined});if(!r.ok)throw Error(await r.text());return r.json()}async function refresh(){try{const s=await api('/status'),r=s.report;selected=r.selected;el('game').textContent=s.game;el('result').textContent=(names[r.decision.state]||'نامشخص')+' · مسیر انتخابی: '+(selected==='direct'?'مستقیم':'پروکسی');el('notice').textContent=s.notice;el('scope').textContent=(r.applied?'تونل روی این رایانه فعال است. ':'فقط آزمون؛ ترافیک بازی هنوز تونل نشده. ')+(r.decision.scope==='service'?'این نتیجه فقط دسترسی HTTPS سرویس است؛ مسابقه بررسی نشده.':'نتیجهٔ واقعی واردشده توسط کاربر.');el('upload').textContent=s.upload;const table=el('pairs');table.replaceChildren();for(const p of r.pairs){const tr=document.createElement('tr');for(const v of [p.target,p.direct.map(x=>x.error||x.status+' · '+x.ms+'ms').join(' / '),p.proxy.map(x=>x.error||x.status+' · '+x.ms+'ms').join(' / ')]){const td=document.createElement('td');td.textContent=v;td.style.overflowWrap='anywhere';tr.append(td)}table.append(tr)}document.querySelectorAll('button').forEach(b=>b.disabled=s.busy||(b.dataset.action==='confirm'&&!s.tun));}catch(e){el('notice').textContent=e.message}}document.addEventListener('click',async e=>{const b=e.target.closest('button[data-action]');if(!b)return;try{await api('/action',{action:b.dataset.action,route:b.dataset.route||selected,result:b.dataset.result});await refresh()}catch(e){el('notice').textContent=e.message}});refresh();setInterval(refresh,2000);
</script></html>`
